  // completed — the «reaches terminal within the wait» shape. Post-rerun,
  // the stub serves the -post.json success when [rerunToSuccess].
  void plantRun(String listJson) {
    if (listJson.isEmpty || listJson == '[]') return;
    final objs = RegExp(r'\{[^}]*\}')
        .allMatches(listJson)
