      // Test seams — production defaults live in the script.
      'PUBDEV_READ_SLEEP_SECS': '0',
      'PUBDEV_POLL_SLEEP_SECS': '0',
      ...extraEnv,
    },
  );
  return VerifyRun(
    res.exitCode,
    '${res.stdout}${res.stderr}',
