      '${publishToNone ? 'publish_to: none\n' : ''}');
  _git(['add', '-A'], cwd: seed);
  _git(['commit', '-q', '-m', bumpSubject], cwd: seed, env: {
    'GIT_COMMITTER_DATE': '${_epoch(now.subtract(bumpAge))}',
    'GIT_AUTHOR_DATE': '${_epoch(now.subtract(bumpAge))}',
