  final res = Process.runSync(
    'bash',
    [File('scripts/verify_pubdev_release.sh').absolute.path],
    workingDirectory: job,
    environment: {
      'PATH': '${stub.bin}:${Platform.environment['PATH']}',
      'FA_REAL_GIT': stub.realGit,
      'GITHUB_REPOSITORY': 'OWNER/REPO',
      'GH_TOKEN': 'stub',

